package com.guocheng.mediapocket;
import android.app.*;import android.content.*;import android.media.AudioManager;import android.os.*;import android.view.*;import android.widget.*;import androidx.media3.common.C;import org.json.*;import java.util.*;
/** Controls operate on the active Media3 instance, and share app preferences with VLC. */
final class Media3Controls {
 final SystemPlayerActivity a;final android.content.SharedPreferences prefs;final LinearLayout top,bottom;final SeekBar seek;final TextView time,sub;final Button play,rate,backward,forward;final GestureDetector gestures;final ScaleGestureDetector scale;boolean dragging,holding,sliding,locked;float heldRate,downX,downY,downBrightness;int downVolume;long hideAt;final AudioManager audio;final Handler handler=new Handler(Looper.getMainLooper());
 final Runnable pulse=new Runnable(){public void run(){if(a.isDestroyed()||a.isFinishing())return;update();handler.postDelayed(this,300);}};
 Media3Controls(SystemPlayerActivity owner,FrameLayout root){
  a=owner;prefs=a.getSharedPreferences("data",0);audio=(AudioManager)a.getSystemService(Context.AUDIO_SERVICE);
  top=new LinearLayout(a);a.top=top;top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(16),dp(24),dp(16),dp(6));top.setBackground(PlayerOverlay.fade(true));
  top.addView(button("‹",()->a.finish()));TextView title=label(a.title,16);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);top.addView(title,new LinearLayout.LayoutParams(0,dp(44),1));top.addView(button("更多",this::more));root.addView(top,new FrameLayout.LayoutParams(-1,-2,Gravity.TOP));
  bottom=new LinearLayout(a);a.bottom=bottom;bottom.setOrientation(LinearLayout.VERTICAL);bottom.setPadding(dp(16),dp(16),dp(16),dp(16));bottom.setBackground(PlayerOverlay.fade(false));
  time=label("00:00 / 00:00",13);bottom.addView(time);seek=new SeekBar(a);seek.setMax(10000);bottom.addView(seek,new LinearLayout.LayoutParams(-1,dp(32)));
  HorizontalScrollView scroller=new HorizontalScrollView(a);scroller.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);
  backward=button("−15秒",()->jump(-1));row.addView(backward);play=button("暂停",()->{if(a.video.wantsPlayback())a.video.pause();else a.video.start();});row.addView(play);forward=button("+15秒",()->jump(1));row.addView(forward);
  rate=button("1.0×",this::speed);row.addView(rate);row.addView(button("比例",this::aspect));row.addView(button("音轨",()->tracks(C.TRACK_TYPE_AUDIO)));row.addView(button("字幕",this::subtitles));
  if(!EpisodeActions.list(a.meta).isEmpty())row.addView(button("series".equals(a.type)?"选集":"版本",this::episodes));scroller.addView(row);bottom.addView(scroller);root.addView(bottom,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));
  sub=label("",20);sub.setGravity(Gravity.CENTER);sub.setShadowLayer(dp(3),1,1,0xff000000);sub.setPadding(dp(20),0,dp(20),dp(18));FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);sp.bottomMargin=dp(160);root.addView(sub,sp);a.video.subtitleView=sub;
  seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar v){dragging=true;}public void onStopTrackingTouch(SeekBar v){a.video.seekTo((int)((long)a.video.getDuration()*v.getProgress()/10000));dragging=false;reveal();}public void onProgressChanged(SeekBar v,int n,boolean user){if(user)time.setText(PlayerOverlayRules.clock((int)((long)a.video.getDuration()*n/10000),a.video.getDuration()));}});
  gestures=new GestureDetector(a,new GestureDetector.SimpleOnGestureListener(){
   @Override public boolean onDown(android.view.MotionEvent e){return true;}
   @Override public boolean onSingleTapConfirmed(android.view.MotionEvent e){if(locked)unlockMenu();else if(top.getVisibility()==View.VISIBLE)hide();else reveal();return true;}
   @Override public boolean onDoubleTap(android.view.MotionEvent e){if(locked)return true;if(e.getX()<a.video.getWidth()/3f)jump(-1);else if(e.getX()>a.video.getWidth()*2f/3)jump(1);else if(PlaybackPrefs.doubleTapCenter(prefs)){if(a.video.wantsPlayback())a.video.pause();else a.video.start();}return true;}
   @Override public void onLongPress(android.view.MotionEvent e){if(locked||sliding)return;heldRate=a.video.speed();holding=true;a.video.speed(PlaybackPrefs.holdRate(prefs));hint("临时 "+PlaybackPrefs.speedLabel(PlaybackPrefs.holdRate(prefs)));}
  });
  scale=new ScaleGestureDetector(a,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScale(ScaleGestureDetector d){if(!locked)a.video.zoom(a.video.zoom*d.getScaleFactor());return true;}});
  a.video.setOnTouchListener((v,e)->touch(e));reveal();PlayerSwitches.restoreBrightness(a);handler.post(pulse);
 }
 int dp(int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}TextView label(String text,int size){TextView t=new TextView(a);t.setText(text==null?"":text);t.setTextSize(size);t.setTextColor(0xffffffff);return t;}
 Button button(String text,Runnable run){Button b=new Button(a);b.setText(text);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(0xffffffff);b.setMinWidth(0);b.setMinimumWidth(0);b.setBackground(PlayerOverlay.ripple(a));b.setPadding(dp(10),0,dp(10),0);b.setOnClickListener(v->{run.run();reveal();});return b;}
 void hint(String text){Toast.makeText(a,text,Toast.LENGTH_SHORT).show();}
 void reveal(){if(locked)return;top.setVisibility(View.VISIBLE);bottom.setVisibility(View.VISIBLE);hideAt=SystemClock.elapsedRealtime()+5000;subtitlePosition();}
 void hide(){top.setVisibility(View.GONE);bottom.setVisibility(View.GONE);subtitlePosition();}
 void subtitlePosition(){FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)sub.getLayoutParams();p.bottomMargin=bottom.getVisibility()==View.VISIBLE?Math.max(dp(140),bottom.getHeight()+dp(10)):dp(20);sub.setLayoutParams(p);}
 void update(){backward.setText("−"+PlaybackPrefs.seekSeconds(prefs)+"秒");forward.setText("+"+PlaybackPrefs.seekSeconds(prefs)+"秒");if(PlaybackPrefs.showBufferSpeed(prefs)&&a.video.player!=null){long bps=androidx.media3.exoplayer.upstream.DefaultBandwidthMeter.getSingletonInstance(a).getBitrateEstimate();PlayerSwitches.BUFFER.put(a,"网络估计 "+(bps/8192)+" KB/s · 已缓冲 "+a.video.getBufferPercentage()+"%");}else PlayerSwitches.BUFFER.remove(a);if(!dragging){time.setText(PlayerOverlayRules.clock(a.video.getCurrentPosition(),a.video.getDuration()));if(a.video.getDuration()>0)seek.setProgress((int)((long)a.video.getCurrentPosition()*10000/a.video.getDuration()));seek.setSecondaryProgress(a.video.getBufferPercentage()*100);}play.setText(a.video.wantsPlayback()?"暂停":"播放");rate.setText(PlaybackPrefs.speedLabel(a.video.speed()));if(!dragging&&!holding&&!CinemaMenu.isOpen(a)&&SystemClock.elapsedRealtime()>hideAt)hide();PlayerSwitches.applyRefresh(a);Media3Sound.tick(a);PlayerOverlay.statusLine(a);DanmuController.attach(a);DanmuController.tick(a);}
 boolean touch(MotionEvent e){
  if(e.getActionMasked()==MotionEvent.ACTION_DOWN){downX=e.getX();downY=e.getY();sliding=false;downVolume=audio==null?0:audio.getStreamVolume(AudioManager.STREAM_MUSIC);downBrightness=a.getWindow().getAttributes().screenBrightness;if(downBrightness<0)downBrightness=.5f;}
  if(!locked)scale.onTouchEvent(e);gestures.onTouchEvent(e);
  if(!locked&&e.getPointerCount()==1&&!holding&&e.getActionMasked()==MotionEvent.ACTION_MOVE){float delta=(downY-e.getY())/Math.max(1,a.video.getHeight());if(Math.abs(e.getY()-downY)>dp(24)&&Math.abs(e.getY()-downY)>Math.abs(e.getX()-downX)){sliding=true;if(downX<a.video.getWidth()/2f){WindowManager.LayoutParams p=a.getWindow().getAttributes();p.screenBrightness=Math.max(.02f,Math.min(1f,downBrightness+delta));a.getWindow().setAttributes(p);PlayerSwitches.saveBrightness(a);}else if(audio!=null){int max=audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);audio.setStreamVolume(AudioManager.STREAM_MUSIC,Math.max(0,Math.min(max,downVolume+Math.round(delta*max))),0);}}}
  if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){if(holding){a.video.speed(heldRate);holding=false;}if(sliding)hideAt=SystemClock.elapsedRealtime()+5000;}
  return true;
 }
 void jump(int direction){a.video.seekTo(Media3ControlRules.seek(a.video.getCurrentPosition(),a.video.getDuration(),direction*PlaybackPrefs.seekMs(prefs)));reveal();}
 void speed(){List<CinemaMenu.Item> rows=new ArrayList<>();for(float v:new float[]{.5f,.75f,1f,1.25f,1.5f,2f,2.5f,3f}){final float value=v;rows.add(CinemaMenu.choice(PlaybackPrefs.speedLabel(v),Math.abs(a.video.speed()-v)<.01f,()->{PlaybackPrefs.setSpeed(prefs,value);a.video.speed(value);}));}CinemaMenu.show(a,"播放速度",rows);}
 void aspect(){List<CinemaMenu.Item> rows=new ArrayList<>();for(int i=0;i<FullscreenRules.MODES.length;i++){final String mode=FullscreenRules.MODES[i];rows.add(CinemaMenu.choice(FullscreenRules.LABELS[i],mode.equals(a.video.aspect),()->{prefs.edit().putString("aspectMode",mode).apply();a.video.aspect(mode);}));}CinemaMenu.show(a,"画面比例",rows);}
 void tracks(int type){List<CinemaMenu.Item> rows=new ArrayList<>();if(type==C.TRACK_TYPE_TEXT)rows.add(CinemaMenu.item("关闭字幕",()->{a.video.selectTrack(type,null);prefs.edit().putBoolean("subtitleDisabled:"+a.watch,true).apply();}));for(Media3VideoView.Track track:a.video.tracks(type))rows.add(CinemaMenu.choice(track.label,track.selected,()->{a.video.selectTrack(type,track);if(type==C.TRACK_TYPE_TEXT)prefs.edit().putBoolean("subtitleDisabled:"+a.watch,false).apply();}));if(rows.isEmpty()){hint("片源尚未返回可选择的音轨");return;}CinemaMenu.show(a,type==C.TRACK_TYPE_TEXT?"内嵌字幕":"音轨",rows);}
 void subtitles(){List<CinemaMenu.Item> rows=new ArrayList<>();rows.add(CinemaMenu.item("内嵌字幕 / 关闭",()->tracks(C.TRACK_TYPE_TEXT)));rows.add(CinemaMenu.item("搜索在线字幕",()->OnlineSubtitleController.open(a)));JSONArray subs=a.source.optJSONArray("subtitles");for(int i=0;subs!=null&&i<subs.length();i++){JSONObject s=subs.optJSONObject(i);if(s==null||s.optString("url").isEmpty())continue;final String url=s.optString("url"),name=s.optString("lang",s.optString("name","片源字幕"));rows.add(CinemaMenu.item(name,()->a.loadSubtitleFile(url,name)));}CinemaMenu.show(a,"字幕",rows);}
 void episodes(){JSONObject server=EmbyStore.get(a,a.serverId);if(server==null){hint("请从影片详情选择剧集");return;}List<CinemaMenu.Item> rows=new ArrayList<>();for(JSONObject video:EpisodeActions.list(a.meta)){String id=video.optString("id");rows.add(CinemaMenu.choice(EpisodeActions.label(video),id.equals(a.watch),()->{a.persist(false);EmbyPlayback.playItem(a,server,EmbyApi.itemOf(id),"",true);}));}CinemaMenu.show(a,"选集",rows);}
 void more(){List<CinemaMenu.Item> rows=new ArrayList<>();rows.add(CinemaMenu.item("播放设置",()->PlayerFeatureSettings.playback(a)));rows.add(CinemaMenu.item(DanmuController.label(a),()->DanmuController.menu(a)));rows.add(CinemaMenu.item("音效",()->Media3Sound.menu(a)));if(a.source.optJSONArray("emby.versions")!=null)rows.add(CinemaMenu.item("切换版本",()->{JSONObject server=EmbyStore.get(a,a.serverId);if(server!=null){a.persist(false);EmbyPlayback.pickVersion(a,server,a.item,a.source.optJSONArray("emby.versions"),true);}}));rows.add(CinemaMenu.item("锁定屏幕",()->{locked=true;hide();hint("已锁定，点画面可解锁");}));rows.add(CinemaMenu.item("旋转屏幕",()->a.setRequestedOrientation(a.getResources().getConfiguration().orientation==2?android.content.pm.ActivityInfo.SCREEN_ORIENTATION_SENSOR_PORTRAIT:android.content.pm.ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE)));rows.add(CinemaMenu.item("用外部播放器打开",a::external));rows.add(CinemaMenu.item("调试信息",()->DebugLog.show(a)));CinemaMenu.show(a,"内置杜比播放设置",rows);}
 void unlockMenu(){CinemaMenu.show(a,"屏幕已锁定",Collections.singletonList(CinemaMenu.item("解锁",()->{locked=false;reveal();})));}
 void dispose(){handler.removeCallbacksAndMessages(null);DanmuController.dispose(a);Media3Sound.release(a);PlayerSwitches.REFRESH.remove(a);PlayerSwitches.BUFFER.remove(a);}
}
